def _runs():
    # Follows the cd and python3 commands in the comments, from a new terminal in /home/sam.
    _here, _last = "/home/sam", "no comment line runs python3"
    for _l in __learner_source__.splitlines():
        _s = _l.strip()
        if not _s.startswith("#"):
            continue
        for _seg in _re.split(r"&&|;", _s.lstrip("#")):
            _m = _re.search(r"(?:^|[\s:$])(cd|python3(?:\.\d+)?|python|py)(?=\s|$)(.*)", _seg)
            if not _m:
                continue
            _cmd, _args = _m.group(1), _m.group(2).split()
            if _cmd == "cd":
                _to = _pp.normpath(_pp.join(_here, _home(_args[0] if _args else "~")))
                if _to in _DIRS:
                    _here = _to
                else:
                    _last = "cd " + _args[0] + " from " + _here + ": no such folder"
            elif _cmd in ("python", "py"):
                _last = _cmd + " is not python3: run the script with python3"
            elif not _args:
                _last = "python3 needs the script's name"
            else:
                _file = _pp.normpath(_pp.join(_here, _home(_args[0])))
                if _file != "/home/sam/desk/trade.py":
                    _last = "python3 " + _args[0] + " from " + _here + " looks for " + _file
                elif _here != "/home/sam/desk":
                    _last = "that runs it from " + _here + ", not from its own folder"
                else:
